#!/usr/bin/env bash
# Question 16: Frontend cannot reach ${Q16_APP}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q16_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q16_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q16_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q16_APP}
  namespace: ${Q16_NS}
spec:
  replicas: 2
  selector:
    matchLabels: { app: ${Q16_APP} }
  template:
    metadata:
      labels: { app: ${Q16_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
---
apiVersion: v1
kind: Service
metadata:
  name: ${Q16_APP}
  namespace: ${Q16_NS}
spec:
  selector: { app: ${Q16_APP} }
  ports: [{ port: 80, targetPort: 80 }]
---
apiVersion: v1
kind: Pod
metadata:
  name: client
  namespace: ${Q16_NS}
  labels: { role: frontend }
spec:
  containers:
    - name: shell
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Pod
metadata:
  name: stranger
  namespace: ${Q16_NS}
  labels: { role: guest }
spec:
  containers:
    - name: shell
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: default-deny
  namespace: ${Q16_NS}
spec:
  podSelector: {}
  policyTypes: [Ingress, Egress]
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: allow-dns
  namespace: ${Q16_NS}
spec:
  podSelector: {}
  policyTypes: [Egress]
  egress:
    - to:
        - namespaceSelector:
            matchLabels: { kubernetes.io/metadata.name: kube-system }
          podSelector:
            matchLabels: { k8s-app: kube-dns }
      ports:
        - { protocol: UDP, port: 53 }
        - { protocol: TCP, port: 53 }
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: frontend-egress
  namespace: ${Q16_NS}
spec:
  podSelector:
    matchLabels: { role: frontend }
  policyTypes: [Egress]
  egress:
    - to:
        - podSelector:
            matchLabels: { app: ${Q16_APP} }
      ports:
        - { protocol: TCP, port: 80 }
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: ${Q16_APP}-ingress
  namespace: ${Q16_NS}
spec:
  podSelector:
    matchLabels: { app: ${Q16_APP} }
  policyTypes: [Ingress]
  ingress:
    - from:
        - podSelector:
            matchLabels: { role: frontend }
      ports:
        - { protocol: TCP, port: 80 }
EOF
kubectl -n "${Q16_NS}" rollout status "deployment/${Q16_APP}" --timeout=240s
if ! kubectl -n "${Q16_NS}" wait --for=condition=Ready pod/client pod/stranger --timeout=180s; then
  kubectl -n "${Q16_NS}" describe pod client stranger >&2 || true
  exit 1
fi

(
case "${Q16_FAULT}" in
  egress-to-label)
    kubectl -n "${Q16_NS}" patch networkpolicy "frontend-egress" --type=json -p '[{"op":"replace","path":"/spec/egress/0/to/0/podSelector/matchLabels","value":{"app":"'"${Q16_APP}"'-v2"}}]'
    ;;
  egress-port)
    kubectl -n "${Q16_NS}" patch networkpolicy "frontend-egress" --type=json -p '[{"op":"replace","path":"/spec/egress/0/ports/0/port","value":8080}]'
    ;;
  frontend-egress-deleted)
    kubectl -n "${Q16_NS}" delete networkpolicy frontend-egress
    ;;
  frontend-egress-selector)
    kubectl -n "${Q16_NS}" patch networkpolicy "frontend-egress" --type=json -p '[{"op":"replace","path":"/spec/podSelector/matchLabels","value":{"role":"front-end"}}]'
    ;;
  netpol-egress-ipblock-except)
    kubectl -n "${Q16_NS}" apply -f - <<< '{"apiVersion":"networking.k8s.io/v1","kind":"NetworkPolicy","metadata":{"name":"frontend-egress-ipblock"},"spec":{"podSelector":{"matchLabels":{"role":"frontend"}},"policyTypes":["Egress"],"egress":[{"to":[{"ipBlock":{"cidr":"0.0.0.0/0","except":["10.0.0.0/8","192.168.0.0/16"]}}],"ports":[{"protocol":"TCP","port":80}]},{"to":[{"namespaceSelector":{"matchLabels":{"kubernetes.io/metadata.name":"kube-system"}},"podSelector":{"matchLabels":{"k8s-app":"kube-dns"}}}],"ports":[{"protocol":"UDP","port":53},{"protocol":"TCP","port":53}]}]}}'
    kubectl -n "${Q16_NS}" delete networkpolicy frontend-egress --ignore-not-found >/dev/null
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q16_FAULT_2}" in
  ingress-port)
    kubectl -n "${Q16_NS}" patch networkpolicy "${Q16_APP}-ingress" --type=json -p '[{"op":"replace","path":"/spec/ingress/0/ports/0/port","value":8080}]'
    ;;
  ingress-from-label)
    kubectl -n "${Q16_NS}" patch networkpolicy "${Q16_APP}-ingress" --type=json -p '[{"op":"replace","path":"/spec/ingress/0/from/0/podSelector/matchLabels","value":{"role":"front-end"}}]'
    ;;
  ingress-namespace-and)
    kubectl -n "${Q16_NS}" patch networkpolicy "${Q16_APP}-ingress" --type=json -p '[{"op":"replace","path":"/spec/ingress/0/from/0","value":{"namespaceSelector":{"matchLabels":{"team":"frontend"}},"podSelector":{"matchLabels":{"role":"frontend"}}}}]'
    ;;
  ingress-pod-selector)
    kubectl -n "${Q16_NS}" patch networkpolicy "${Q16_APP}-ingress" --type=json -p '[{"op":"replace","path":"/spec/podSelector/matchLabels","value":{"app":"'"${Q16_APP}"'-v2"}}]'
    ;;
  ingress-port-443)
    kubectl -n "${Q16_NS}" patch networkpolicy "${Q16_APP}-ingress" --type=json -p '[{"op":"replace","path":"/spec/ingress/0/ports","value":[{"protocol":"TCP","port":443}]}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
# The question only makes sense if the client really is cut off.
for _ in $(seq 1 30); do
  kubectl -n "${Q16_NS}" exec client -- wget -qO- -T 3 "http://${Q16_APP}" 2>/dev/null | grep -q nginx || exit 0
  sleep 2
done
echo "the client can still reach ${Q16_APP}" >&2
exit 1
)
